/**
 * Markdown.Inlines: a block’s inline nodes, each as the member or element that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type JSX } from 'solid-js'

import { Each, claimSlot, inlineText, scope, type MarkdownInline } from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import Citation from './Citation'
import Code from '../structure/Code'
import Link from '../controls/Link'
import type { CitationSource } from './SourceList'

export interface MarkdownInlinesProps {
  nodes: MarkdownInline[]
  sources: CitationSource[]
}

/** Markdown.Inlines: a block’s inline nodes, each as the member or element that draws its kind. */
export default function MarkdownInlines(given: MarkdownInlinesProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <Each of={props.nodes} by={(_node, index) => index} renew>
        {(node) => (
          <>
            {node.kind === 'text' ? (
              node.text
            ) : node.kind === 'code' ? (
              <Code>{node.text}</Code>
            ) : node.kind === 'strong' ? (
              <strong>
                <MarkdownInlines nodes={node.children} sources={props.sources} />
              </strong>
            ) : node.kind === 'em' ? (
              <em>
                <MarkdownInlines nodes={node.children} sources={props.sources} />
              </em>
            ) : node.kind === 'strike' ? (
              <s>
                <MarkdownInlines nodes={node.children} sources={props.sources} />
              </s>
            ) : node.kind === 'break' ? (
              <br />
            ) : node.kind === 'link' ? (
              <Link href={node.href} external={/^(https?:|mailto:|\/\/)/i.test(node.href)}>
                {inlineText(node.children)}
              </Link>
            ) : node.kind === 'image' ? (
              <img
                class={styles.image}
                src={node.src}
                alt={node.alt}
                loading="lazy"
                draggable="false"
              />
            ) : node.kind === 'citation' && props.sources[node.index - 1] !== undefined ? (
              <Citation index={node.index} source={props.sources[node.index - 1]!} />
            ) : node.kind === 'citation' ? (
              `[${node.index}]`
            ) : null}
          </>
        )}
      </Each>
    )
  })
}
